sparql_response:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?airport ?countryName WHERE {
  VALUES ?airport {
    <http://dbpedia.org/resource/Quaqtaq_Airport>
    <http://dbpedia.org/resource/Fort_Nelson/Gordon_Field_Airport>
  }
  ?airport dbo:location ?loc .
  ?loc dbo:country ?country .
  ?country rdfs:label ?countryName .
  FILTER (lang(?countryName) = "en")
}
LIMIT 100

